#!/usr/bin/env python3
"""Sum numeric columns of a CSV file and print the result as JSON."""

import argparse
import csv
import json
import sys


def is_number(value):
    """Return True if value can be parsed as a float."""
    try:
        float(value)
        return True
    except (TypeError, ValueError):
        return False


def sum_numeric_columns(csv_path):
    """Return a dict mapping numeric column names to their column sums."""
    with open(csv_path, newline="") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            return {}

        # First data row determines which columns are numeric.
        # We'll keep track of all rows to handle empty strings gracefully.
        numeric_columns = set(reader.fieldnames)
        rows = []
        for row in reader:
            rows.append(row)

    if not rows:
        return {}

    # Determine numeric columns: a column is numeric if every non-empty value
    # in that column parses as a float.
    for col in list(numeric_columns):
        for row in rows:
            value = row.get(col, "")
            if value is None:
                value = ""
            value = value.strip()
            if value == "":
                continue
            if not is_number(value):
                numeric_columns.discard(col)
                break

    totals = {}
    for col in numeric_columns:
        total = 0.0
        for row in rows:
            value = (row.get(col) or "").strip()
            if value == "":
                continue
            total += float(value)
        totals[col] = total

    return totals


def main():
    parser = argparse.ArgumentParser(
        description="Print a JSON mapping of numeric CSV columns to their sums."
    )
    parser.add_argument("csv_path", help="Path to the CSV file")
    args = parser.parse_args()

    try:
        totals = sum_numeric_columns(args.csv_path)
    except FileNotFoundError:
        print(f"Error: file not found: {args.csv_path}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        sys.exit(1)

    print(json.dumps(totals))


if __name__ == "__main__":
    main()
