    root = os.path.abspath(args.root)
    if not os.path.isdir(root):
        parser.error(f"not a directory: {root}")

    duplicates = find_duplicates(root)

    if not duplicates:
        if not args.quiet:
            print(f"No duplicate files found under {root}")
        return 0

    total_groups = len(duplicates)
    total_files = 0
    wasted = 0

