#!/usr/bin/env python3
"""Find duplicate files in a directory tree by SHA-256 hash.

Walks a directory tree, hashes every regular file with SHA-256, and prints
groups of files that share the same hash (i.e. duplicate contents).

Usage:
    python dupes.py [PATH ...] [options]
"""

from __future__ import annotations

import argparse
import hashlib
import os
import sys
from collections import defaultdict
from typing import Iterable

CHUNK_SIZE = 1024 * 1024  # 1 MiB


def hash_file(path: str, chunk_size: int = CHUNK_SIZE) -> str:
    """Return the hex SHA-256 digest of the file at *path*."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            h.update(chunk)
    return h.hexdigest()


def iter_files(roots: Iterable[str]):
    """Yield all regular file paths under each root, following symlinks safely."""
    for root in roots:
        if os.path.isfile(root):
            yield root
            continue
        for dirpath, _dirnames, filenames in os.walk(root):
            for name in filenames:
                full = os.path.join(dirpath, name)
                # Skip broken symlinks and other non-regular files.
                if os.path.isfile(full):
                    yield full


def find_duplicates(
    roots: Iterable[str],
    min_size: int = 0,
    verbose: bool = False,
) -> dict[str, list[str]]:
    """Return a mapping {sha256_hex: [paths...]} for files sharing content.

    Only hashes with 2 or more entries are returned.
    """
    by_hash: dict[str, list[str]] = defaultdict(list)
    by_size: dict[int, list[str]] = defaultdict(list)

    # First pass: group by size. Different sizes can never have the same hash,
    # so skip hashing the majority of files.
    for path in iter_files(roots):
        try:
            size = os.path.getsize(path)
        except OSError as e:
            if verbose:
                print(f"skip {path}: {e}", file=sys.stderr)
            continue
        if size < min_size:
            continue
        by_size[size].append(path)

    # Second pass: hash only files whose size has collisions.
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        for path in paths:
            try:
                digest = hash_file(path)
            except OSError as e:
                if verbose:
                    print(f"skip {path}: {e}", file=sys.stderr)
                continue
            by_hash[digest].append(path)

    return {h: ps for h, ps in by_hash.items() if len(ps) > 1}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Find duplicate files by SHA-256 hash."
    )
    parser.add_argument(
        "paths",
        nargs="*",
        default=["."],
        help="directories (or files) to scan (default: current directory)",
    )
    parser.add_argument(
        "-m", "--min-size",
        type=int,
        default=0,
        metavar="BYTES",
        help="ignore files smaller than BYTES (default: 0)",
    )
    parser.add_argument(
        "-q", "--quiet",
        action="store_true",
        help="only print the count of duplicate groups",
    )
    parser.add_argument(
        "-v", "--verbose",
        action="store_true",
        help="report files that could not be read",
    )
    args = parser.parse_args(argv)

    duplicates = find_duplicates(
        args.paths, min_size=args.min_size, verbose=args.verbose
    )

    if not duplicates:
        if not args.quiet:
            print("No duplicate files found.")
        return 0

    groups = sorted(
        duplicates.items(),
        key=lambda item: (-len(item[1]), item[0]),
    )

    if args.quiet:
        print(f"{len(groups)} duplicate group(s)")
        return 0

    total_wasted = 0
    for digest, paths in groups:
        try:
            size = os.path.getsize(paths[0])
        except OSError:
            size = 0
        total_wasted += size * (len(paths) - 1)

        print(f"\nSHA-256: {digest}")
        print(f"  size: {size} bytes  copies: {len(paths)}")
        for p in sorted(paths):
            print(f"    {p}")

    print(f"\n{len(groups)} duplicate group(s), "
          f"~{total_wasted} bytes reclaimable")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        sys.exit(130)
```

Key design points:

- **Two-pass scan**: first groups files by size, then SHA-256-hashes only size-colliding candidates. This avoids hashing most files and is much faster on real directories.
- **Robust walking**: `os.walk` plus `os.path.isfile` filtering skips broken symlinks, sockets, FIFOs, etc. `--verbose` reports unreadable files without aborting.
- **Streaming hash**: hashes in 1 MiB chunks so large files don't blow up memory.
- **Deterministic output**: groups sorted by count then hash; paths within a group sorted alphabetically.
- **`argparse` + `if __name__ == "__main__"`**: as requested, with `--min-size`, `--quiet`, `--verbose` options and multiple root paths.

