#!/usr/bin/env python3
"""Find duplicate files in a directory tree by SHA-256 hash."""

import argparse
import hashlib
import sys
from collections import defaultdict
from pathlib import Path


CHUNK_SIZE = 1024 * 1024  # 1 MiB


def hash_file(path: Path, chunk_size: int = CHUNK_SIZE) -> str:
    """Return the hex SHA-256 digest of the given file."""
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root: Path, follow_symlinks: bool = False) -> dict:
    """Walk `root` and return {sha256: [paths...]} for hashes with >1 file."""
    hashes = defaultdict(list)
    errors = []

    if not root.exists():
        raise FileNotFoundError(f"Path does not exist: {root}")

    if root.is_file():
        hashes[hash_file(root)].append(root)
        return hashes

    for path in root.rglob("*"):
        try:
            if path.is_symlink() and not follow_symlinks:
                continue
            if not path.is_file():
                continue
            hashes[hash_file(path)].append(path)
        except (OSError, PermissionError) as exc:
            errors.append((path, exc))

    if errors:
        print(f"Warning: skipped {len(errors)} file(s) due to errors", file=sys.stderr)
        for p, exc in errors:
            print(f"  {p}: {exc}", file=sys.stderr)

    return hashes


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        description="Find duplicate files by SHA-256 hash."
    )
    parser.add_argument(
        "directory",
        type=Path,
        help="Directory to scan (or a single file).",
    )
    parser.add_argument(
        "-f",
        "--follow-symlinks",
        action="store_true",
        help="Follow symlinks when walking the tree.",
    )
    parser.add_argument(
        "--min-size",
        type=int,
        default=0,
        help="Only consider files at least this many bytes (default: 0).",
    )
    args = parser.parse_args(argv)

    try:
        hashes = find_duplicates(args.directory, args.follow_symlinks)
    except FileNotFoundError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1

    # Filter by size if requested and group duplicates
    duplicates = {}
    for digest, paths in hashes.items():
        if len(paths) < 2:
            continue
        if args.min_size:
            # All duplicates share content, so size of any one is the file size
            try:
                size = paths[0].stat().st_size
            except OSError:
                continue
            if size < args.min_size:
                continue
        duplicates[digest] = sorted(paths)

    if not duplicates:
        print("No duplicate files found.")
        return 0

    total_wasted = 0
    print(f"Found {len(duplicates)} duplicate group(s):\n")
    for i, (digest, paths) in enumerate(sorted(duplicates.items()), start=1):
        try:
            size = paths[0].stat().st_size
        except OSError:
            size = 0
        wasted = size * (len(paths) - 1)
        total_wasted += wasted
        print(f"[{i}] SHA-256: {digest}")
        print(f"    Size: {size} bytes  |  Copies: {len(paths)}  |  Wasted: {wasted} bytes")
        for p in paths:
            print(f"      {p}")
        print()

    print(f"Total space wasted by duplicates: {total_wasted} bytes")
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

