import os
import sys


def three_largest_files(root):
    """Return a list of (size, path) tuples for the 3 largest files under root."""
    largest = []  # min-heap of (size, path)
    seen = set()

    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            path = os.path.join(dirpath, name)
            try:
                st = os.stat(path)
            except OSError:
